window.AUTH=window.AUTH||{};window.AUTH["19-508"]={"d":"19-508","id":"2020/19-508","n":"AMG Capital Management, LLC v. Federal Trade Commission","briefs":[{"k":"respondent","label":"Brief of respondents Credit Bureau Center, LLC, et al.","date":"2020-09-25","url":"https://www.supremecourt.gov/DocketPDF/19/19-508/154980/20200925145735209_19-825%20FTC%20Merits%20Brief%209-25%20final.pdf","side":"res","n":90},{"k":"petitioner","label":"Brief of petitioners AMG Capital Management, LLC, et al.","date":"2020-09-25","url":"https://www.supremecourt.gov/DocketPDF/19/19-508/154981/20200925174040692_19-508%20ts%20AMG%20Capital%20Mgmt.%20LLC%20merits%20brief%20PDF-A.pdf","side":"pet","n":100},{"k":"respondent","label":"Brief of respondent Federal Trade Commission","date":"2020-11-30","url":"https://www.supremecourt.gov/DocketPDF/19/19-508/162011/20201130120930570_19-508bs.pdf","side":"res","n":103},{"k":"reply","label":"Reply of petitioners AMG Capital Management, LLC, et al.","date":"2020-12-30","url":"https://www.supremecourt.gov/DocketPDF/19/19-508/164976/20201230120921108_Tucker%20Reply%20Brief%20-%20FINAL.pdf","side":"pet","n":49}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us1r28_758b.pdf","tr":true,"items":[{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"9, 11, 37, 38","1":"36, 37, 40","2":"13, 34, 35","3":"20, 22, 23"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"California v. Am. Stores Co.","cite":"495 U.S. 271","y":1990,"id":"1989/89-258","sc":1,"sum":"Divestiture is a form of \"injunctive relief\" authorized by § 16.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 15","2":"37","3":"6, 7, 23"}},{"t":"case","label":"California v. Sierra Club","cite":"451 U.S. 287","y":1981,"id":"1980/79-1252","sc":1,"sum":"Section 10 of the Rivers and Harbors AppropriationAct of 1899 (Act) prohibits \"[t]he creation of any obstruction not affirmatively authorized by Congress, to the navigable capacity of any of the waters of the United States.\" An environmental organization and two private citizens (hereafter respondents) brought an action in Federal District Court seeking to enjoin, as a violation of § 10, the construction and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"City of Harrisonville v. W. S. Dickey Clay Mfg. Co.","cite":"289 U.S. 334","y":1933,"id":"scdb/1932-078","sc":1,"by":{"0":"19"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"eBay Inc. v. MercExchange, L.L.C.","cite":"547 U.S. 388","y":2006,"id":"2005/05-130","sc":1,"sum":"Held that the appeals court's general rule was an unwarranted departure from the traditional four-part test applied to determine whether an injunction is necessary.","sumSrc":"Oyez","by":{"0":"2, 18, 20, 42"}},{"t":"case","label":"Franks v. Bowman Transp. Co.","cite":"424 U.S. 747","y":1976,"id":"1975/74-728","sc":1,"sum":"In a class action against respondent employer and certain labor unions (of which respondent union is the successor) petitioners alleged various racially discriminatory employment practices in violation of Title VII of the Civil Rights Act of 1964 (Act), especially with respect to employment of over-the-road (OTR) truck drivers. After certifying the action as a class action and, inter alia, designating one of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"FTC v. Amy Travel Serv., Inc.","cite":"875 F.2d 564","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/875/564/","by":{"0":"7, 8","1":"10","2":"8, 27"}},{"t":"case","label":"FTC v. Bronson Partners, LLC","cite":"654 F.3d 359","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/654/359/","by":{"0":"13, 41","1":"10, 33, 44","2":"8"}},{"t":"case","label":"FTC v. Commerce Planet, Inc.","cite":"815 F.3d 593","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/815/593/","op":2,"sum":"Holding that Section 13(b) permits “monetary relief that would traditionally be viewed as ‘legal’ ” (citation omitted).","sumSrc":"brief:0","by":{"0":"passim","1":"passim"}},{"t":"case","label":"FTC v. Dantuma","cite":"748 F. App’x 735","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/748/735/","by":{"0":"34, 42","1":"29"}},{"t":"case","label":"FTC v. Real Wealth, Inc.","cite":"2011 WL 3206887","y":2011,"court":"W.D. Mo. July 28","by":{"0":"34"}},{"t":"case","label":"FTC v. Verity Int’l, Ltd.","cite":"443 F.3d 48","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/443/48/","by":{"0":"12, 41, 45","1":"45"}},{"t":"case","label":"Gebser v. Lago Vista Indep. Sch. Dist.","cite":"524 U.S. 274","y":1998,"id":"1997/96-1866","sc":1,"sum":"In a 5-to-4 decision the Court held that two minimal criteria must be met in order for an aggrieved party to recover sexual harassment damages under the Amendments. First, the party must show that a school district official, with the ability to institute corrective measures, knew of the forbidden conduct.","sumSrc":"Oyez","by":{"0":"31, 33","1":"29"}},{"t":"case","label":"Great-West Life & Annuity Ins. Co. v. Knudson","cite":"534 U.S. 204","y":2002,"id":"2001/99-1786","sc":1,"ar":2,"sum":"The Court held that because Great-West is seeking legal relief - the imposition of personal liability on Knudson for a contractual obligation to pay money - ERISA does not authorize this action.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"16, 32, 54","3":"6, 11, 12, 23"}},{"t":"case","label":"Gwaltney of Smithfield, Ltd. v. Chesapeake Bay Found., Inc.","cite":"484 U.S. 49","y":1987,"id":"1987/86-473","sc":1,"sum":"Section 505(a) of the Clean Water Act authorizes private citizens to commence a civil action for injunctive relief and/or the imposition of civil penalties in federal district court against any person \"alleged to be in violation\" of the conditions of a National Pollutant Discharge Elimination System (NPDES) permit. Between 1981 and 1984, petitioner repeatedly violated the conditions of its NPDES permit by exceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Karahalios v. Nat’l Fed’n of Fed. Emps., Local 1263","cite":"489 U.S. 527","y":1989,"id":"1988/87-636","sc":1,"sum":"Title VII of the CSRA does not confer on federal employees a private cause of action against a breach by a union representing such employees of its statutory duty of fair representation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Kokesh v. SEC","cite":"137 S. Ct. 1635","y":2017,"id":"2016/16-529","sc":1,"sum":"The Court held that Securities and Exchange Commission (SEC) disgorgement functions as a penalty, and therefore is subject to the five-year statute of limitations.Commission seeking “disgorgement,” or payment, of illegally obtained funds.","sumSrc":"Oyez","by":{"0":"34","1":"29, 42"}},{"t":"case","label":"Lacassagne v. Chapuis","cite":"144 U.S. 119","y":1892,"id":"scdb/1891-153","sc":1,"sum":"Under a writ of possession, on a judgment entered in January, 1886, in a suit brought in a Circuit Court of the United States by C. against M. in March, 1884, L. was evicted from land, and the agent of C. was put in possession. X. was in possession under a sheriff’s deed made in August, 1885, under proceedings in another suit against M. X. brought a suit in equity, in the same Circuit Court, in April, 1886, against …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"17","1":"2, 22, 23, 24","2":"31","3":"4"}},{"t":"case","label":"Liu v. SEC","cite":"140 S. Ct. 1936","y":2020,"id":"2019/18-1501","sc":1,"sum":"The Court held that the Securities and Exchange Commission may seek and obtain disgorgement from a court as “equitable relief” for a securities law violation, subject to certain restrictions.","sumSrc":"Oyez","by":{"0":"13, 44, 47","1":"passim","2":"passim","3":"23, 25, 26, 27"}},{"t":"case","label":"Los Angeles County v. Humphries","cite":"562 U.S. 29","y":2010,"id":"2010/09-350","sc":1,"sum":"The Court held that plaintiffs seeking declaratory relief against a local public entity must demonstrate that the constitutional violation in question was the result of the public entity's policy, custom, or practice.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Mass. Mut. Life Ins. Co. v. Russell","cite":"473 U.S. 134","y":1985,"id":"1984/84-9","sc":1,"sum":"Section 409(a) does not provide a cause of action for extracontractual damages to a beneficiary caused by improper or untimely processing of benefit claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Meghrig v. KFC Western, Inc.","cite":"516 U.S. 479","y":1996,"id":"1995/95-83","sc":1,"op":3,"ar":2,"sum":"In a unanimous opinion delivered by Justice Sandra Day O'Connor the Court held that section 6972 does not authorize a private cause of action to recover the prior cost of cleaning up toxic waste that does not, at the time of suit, continue to pose an endangerment to health or the environment.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"14, 35, 36","3":"19, 23, 24"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"op":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 36, 45","1":"24","2":"20, 32, 34, 54","3":"3, 11, 12"}},{"t":"case","label":"Mitchell v. Robert DeMario Jewelry, Inc.","cite":"361 U.S. 288","y":1960,"id":"1959/39","sc":1,"op":6,"sum":"In an action by the Secretary of Labor under § 17 of the Fair Labor Standards Act of 1938, as amended, to restrain violations of § 15 (a) (3), a district court has jurisdiction to order an employer to reimburse employees unlawfully discharged or otherwise discriminated against for wages lost because of that discharge or discrimination.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"8, 13, 17, 24, 33, 34","3":"21, 22, 23"}},{"t":"case","label":"Montantile v. Bd. of Trs. of Nat’l Elevator Indus. Health Benefit Plan","cite":"136 S. Ct. 651","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/651/","sc":1,"sum":"Rejecting argument that statutory language permitting “other appropriate equitable relief” grants courts “ancillary jurisdiction to award complete relief”.","sumSrc":"brief:0","by":{"0":"36, 46"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"0":"14","1":"20, 35","2":"48","3":"4, 17"}},{"t":"case","label":"Owner-Operator Indep. Drivers Ass’n v. Landstar Sys., Inc.","cite":"622 F.3d 1307","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/622/1307/","by":{"0":"23"}},{"t":"case","label":"Petrella v. Metro-Goldwyn-Mayer, Inc.","cite":"572 U.S. 663","y":2014,"id":"2013/12-1315","sc":1,"sum":"The Court held that the doctrine of laches could not be used to prevent a copyright suit that seeks relief for damages that occurred within the three-year window allowed by the Copyright Act.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Porter v. Warner Holding Co.","cite":"328 U.S. 395","y":1946,"id":"scdb/1945-032","sc":1,"op":7,"ar":13,"sum":"1. In an.enforcement proceeding under § 205 (a) of the Emergency Price Control Act of 1942, a Federal District Court has power to order restitution of rents collected by a landlord in excess of maximums established by regulations issued under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 34, 35","1":"passim","2":"passim","3":"20, 21, 22, 23"}},{"t":"case","label":"Rondeau v. Mosinee Paper Corp.","cite":"422 U.S. 49","y":1975,"id":"1974/74-415","sc":1,"sum":"A showing of irreparable harm, in accordance with traditional principles of equity, is necessary before a private litigant can obtain injunctive relief based upon § 13 (d) of the Securities Exchange Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"0":"30, 38"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Sampson v. Murray","cite":"415 U.S. 61","y":1974,"id":"1973/72-403","sc":1,"sum":"Upon being notified that she was' going to be discharged on a specific date from her position as aprobationary Government employee, respondent filed this action claiming that the applicable Civil Service regulations for discharge of probationary employees had not been followed, and seeking a temporary injunction against her dismissal pending an administrative appeal to the Civil Service Commission (CSC). The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 18, 19"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Simmons v. Himmelreich","cite":"136 S. Ct. 1843","y":2016,"id":"2015/15-109","sc":1,"sum":"The Court determined that the judgment bar of the Federal Tort Claims Act (FTCA) does not apply to claims dismissed for falling under the exceptions to the FTCA.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"0":"2, 17","1":"23"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"15","2":"20","3":"4"}},{"t":"case","label":"Tex. & Pac. Ry. Co. v. Abilene Cotton Oil Co.","cite":"204 U.S. 426","y":1907,"id":"scdb/1906-159","sc":1,"sum":"Where defendant in the state court contends that, consistently, with the Interstate Commerce Act, the state court hks no power to grant the relief, and such contention is essentially involved and expressly, and, in order to support the judgment, necessarily, decided adversely to the defendant, a Federal question exists and this court' can review the judgment on writ of error under § 709,'.Rev. Stat.'","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30, 31","1":"32, 43","3":"20"}},{"t":"case","label":"United States v. Oregon State Med. Soc’y","cite":"343 U.S. 326","y":1952,"id":"scdb/1951-073","sc":1,"op":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 15, 16, 26"}},{"t":"case","label":"United States v. Philip Morris USA Inc.","cite":"396 F.3d 1190","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/396/1190/","sum":"Concluding that a statutory authorization “to prevent and restrain” violations “indicates that the jurisdiction is limited to forward-looking remedies that are aimed at future violations”.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"United States v. W. T. Grant Co.","cite":"345 U.S. 629","y":1953,"id":"scdb/1952-095","sc":1,"sum":"Under § 15 of the Clayton Act, the United States sued in a federal district court to enjoin an individual and six corporations from violating § 8 through the holding by the individual of interlocking directorates in three pairs of competing corporations. Thereafter, the individual resigned his directorship in one out of each pair of corporatiQns and filed affidavits disclaiming any intention of resuming such …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","2":"32"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Dukes","cite":"564 U.S. 338","y":2011,"id":"2010/10-277","sc":1,"sum":"The Court held that the small group who initiated a lawsuit could not represent all of Wal-Mart's female employees, and therefore could not bring a class action lawsuit against Wal-Mart.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Weinberger v. Romero-Barcelo","cite":"456 U.S. 305","y":1982,"id":"1981/80-1990","sc":1,"sum":"Held that the district court was not obligated to enjoin the Navy from operating on and around Vieques island. He emphasized the traditional flexibility of equitable remedies and courts’ responsibility to balance plaintiffs’ need for an injunction with the public utility of the enjoined action.","sumSrc":"Oyez","by":{"0":"18, 19","2":"25, 41"}},{"t":"case","label":"Page(s) White v. Sparkill Realty Corp.","cite":"280 U.S. 500","y":1930,"id":"scdb/1929-123","sc":1,"op":10,"sum":"1. A suit in equity for an injunction to eject state officials from.land, of which they have taken exclusive possession under claim of right pursuant to a state expropriation statute, will not lie in 4 WHITE v. SPARKILL REALTY CO. Argument for Appellants. federal district court, even though the validity of the statute under the federal -Constitution be challenged by the bill. The remedy at law is adequate.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 20"}},{"t":"case","label":"Whitehead v. Shattuck","cite":"138 U.S. 146","y":1891,"id":"scdb/1890-100","sc":1,"sum":"The bill alleged that the plaintiff was the owner in fee of the premises, but held the title as trustee; that notwithstanding his ownership of the property and his right to its immediate possession and enjoyment, the defendants claimed title to it and were in its possession, holding the same openly and adversely to him; that their claim of title was without foundation in law or equity; and that it was made in fraud …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"law","label":"Magnuson-Moss Warranty—Federal Trade Commission Improvement Act, Pub. L. No. 93-637","url":"https://www.govinfo.gov/link/statute/88/2183","by":{"0":"4, 5, 28","1":"5","2":"6, 43"}},{"t":"law","label":"Trans-Alaska Pipeline Authorization Act, Pub. L. No. 93-153","url":"https://www.govinfo.gov/link/statute/87/576","by":{"0":"5, 6, 28","1":"6, 21","2":"4, 6"}},{"t":"usc","label":"15 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/15/41","stext":{"head":"§41. Federal Trade Commission established; membership; vacancies; seal","paras":[[0,"A commission is created and established, to be known as the Federal Trade Commission (hereinafter referred to as the Commission), which shall be composed of five Commissioners, who shall be appointed by the President, by and with the advice and consent of the Senate. Not more than three of the Commissioners shall be members of the same political party. The first Commissioners appointed shall continue in office for terms of three, four, five, six, and seven years, respectively, from September 26, 1914, the term of each to be designated by the President, but their successors shall be appointed for terms of seven years, except that any person chosen to fill a vacancy shall be appointed only for the unexpired term of the Commissioner whom he shall succeed: Provided, however, That upon the expiration of his term of office a Commissioner shall continue to serve until his successor shall have been appointed and shall have qualified..1 The President shall choose a chairman from the Commission's membership. No Commissioner shall engage in any other business, vocation, or employment. Any Commissioner may be removed by the President for inefficiency, neglect of duty, or malfeasance in office. A vacancy in the Commission shall not impair the right of the remaining Commissioners to exercise all the powers of the Commission."],[0,"The Commission shall have an official seal, which shall be judicially noticed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/41?type=usc&year=mostrecent&link-type=html"},"head":"§41. Federal Trade Commission established; membership; vacancies; seal","tname":"Commerce and Trade","by":{"0":"3","1":"passim","3":"passim"}},{"t":"usc","label":"15 U.S.C. § 45","url":"https://www.law.cornell.edu/uscode/text/15/45","subs":["(a)","(a)(2)","(b)","(c)","(g)","(l)","(m)","(m)(1)","(m)(1)(A)","(m)(1)(B)","(a)(1)","(a)(4)"],"stext":{"head":"§45. Unfair methods of competition unlawful; prevention by Commission","paras":[[0,"(a) Declaration of unlawfulness; power to prohibit unfair practices; inapplicability to foreign trade"],[0,"(1) Unfair methods of competition in or affecting commerce, and unfair or deceptive acts or practices in or affecting commerce, are hereby declared unlawful."],[0,"(2) The Commission is hereby empowered and directed to prevent persons, partnerships, or corporations, except banks, savings and loan institutions described in section 57a(f)(3) of this title, Federal credit unions described in section 57a(f)(4) of this title, common carriers subject to the Acts to regulate commerce, air carriers and foreign air carriers subject to part A of subtitle VII of title 49, and persons, partnerships, or corporations insofar as they are subject to the Packers and Stockyards Act, 1921, as amended [7 U.S.C. 181 et seq.], except as provided in section 406(b) of said Act [7 U.S.C. 227(b)], from using unfair methods of competition in or affecting commerce and unfair or deceptive acts or practices in or affecting commerce."],[0,"(3) This subsection shall not apply to unfair methods of competition involving commerce with foreign nations (other than import commerce) unless—"],[1,"(A) such methods of competition have a direct, substantial, and reasonably foreseeable effect—"],[2,"(i) on commerce which is not commerce with foreign nations, or on import commerce with foreign nations; or"],[2,"(ii) on export commerce with foreign nations, of a person engaged in such commerce in the United States; and"],[1,"(B) such effect gives rise to a claim under the provisions of this subsection, other than this paragraph."],[0,"If this subsection applies to such methods of competition only because of the operation of subparagraph (A)(ii), this subsection shall apply to such conduct only for injury to export business in the United States."],[0,"(4)(A) For purposes of subsection (a), the term \"unfair or deceptive acts or practices\" includes such acts or practices involving foreign commerce that—"],[1,"(i) cause or are likely to cause reasonably foreseeable injury within the United States; or"],[1,"(ii) involve material conduct occurring within the United States."],[0,"(B) All remedies available to the Commission with respect to unfair and deceptive acts or practices shall be available for acts and practices described in this paragraph, including restitution to domestic or foreign victims."],[0,"(b) Proceeding by Commission; modifying and setting aside orders"],[0,"Whenever the Commission shall have reason to believe that any such person, partnership, or corporation has been or is using any unfair method of competition or unfair or deceptive act or practice in or affecting commerce, and if it shall appear to the Commission that a proceeding by it in respect thereof would be to the interest of the public, it shall issue and serve upon such person, partnership, or corporation a complaint stating its charges in that respect and containing a notice of a hearing upon a day and at a place therein fixed at least thirty days after the service of said complaint. The person, partnership, or corporation so complained of shall have the right to appear at the place and time so fixed and show cause why an order should not be entered by the Commission requiring such person, partnership, or corporation to cease and desist from the violation of the law so charged in said complaint. Any person, partnership, or corporation may make application, and upon good cause shown may be allowed by the Commission to intervene and appear in said proceeding by counsel or in person. The testimony in any such proceeding shall be reduced to writing and filed in the office of the Commission. If upon such hearing the Commission shall be of the opinion that the method of competition or the act or practice in question is prohibited by this subchapter, it shall make a report in writing in which it shall state its findings as to the facts and shall issue and cause to be served on such person, partnership, or corporation an order requiring such person, partnership, or corporation to cease and desist from using such method of competition or such act or practice. Until the expiration of the time allowed for filing a petition for review, if no such petition has been duly filed within such time, or, if a petition for review has been filed within such time then until the record in the proceeding has been filed in a court of appeals of the United States, as hereinafter provided, the Commission may at any time, upon such notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any report or any order made or issued by it under this section. After the expiration of the time allowed for filing a petition for review, if no such petition has been duly filed within such time, the Commission may at any time, after notice and opportunity for hearing, reopen and alter, modify, or set aside, in whole or in part any report or order made or issued by it under this section, whenever in the opinion of the Commission conditions of fact or of law have so changed as to require such action or if the public interest shall so require, except that (1) the said person, partnership, or corporation may, within sixty days after service upon him or it of said report or order entered after such a reopening, obtain a review thereof in the appropriate court of appeals of the United States, in the manner provided in subsection (c) of this section; and (2) in the case of an order, the Commission shall reopen any such order to consider whether such order (including any affirmative relief provision contained in such order) should be altered, modified, or set aside, in whole or in part, if the person, partnership, or corporation involved files a request with the Commission which makes a satisfactory showing that changed conditions of law or fact require such order to be altered, modified, or set aside, in whole or in part. The Commission shall determine whether to alter, modify, or set aside any order of the Commission in response to a request made by a person, partnership, or corporation under paragraph 1 (2) not later than 120 days after the date of the filing of such request."],[0,"(c) Review of order; rehearing"],[0,"Any person, partnership, or corporation required by an order of the Commission to cease and desist from using any method of competition or act or practice may obtain a review of such order in the court of appeals of the United States, within any circuit where the method of competition or the act or practice in question was used or where such person, partnership, or corporation resides or carries on business, by filing in the court, within sixty days from the date of the service of such order, a written petition praying that the order of the Commission be set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Commission, and thereupon the Commission shall file in the court the record in the proceeding, as provided in section 2112 of title 28. Upon such filing of the petition the court shall have jurisdiction of the proceeding and of the question determined therein concurrently with the Commission until the filing of the record and shall have power to make and enter a decree affirming, modifying, or setting aside the order of the Commission, and enforcing the same to the extent that such order is affirmed and to issue such writs as are ancillary to its jurisdiction or are necessary in its judgement to prevent injury to the public or to competitors pendente lite. The findings of the Commission as to the facts, if supported by evidence, shall be conclusive. To the extent that the order of the Commission is affirmed, the court shall thereupon issue its own order commanding obedience to the terms of such order of the Commission. If either party shall apply to the court for leave to adduce additional evidence, and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Commission, the court may order such additional evidence to be taken before the Commission and to be adduced upon the hearing in such manner and upon such terms and conditions as to the court may seem proper. The Commission may modify its findings as to the facts, or make new findings, by reason of the additional evidence so taken, and it shall file such modified or new findings, which, if supported by evidence, shall be conclusive, and its recommendation, if any, for the modification or setting aside of its original order, with the return of such additional evidence. The judgment and decree of the court shall be final, except that the same shall be subject to review by the Supreme Court upon certiorari, as provided in section 1254 of title 28."],[0,"(d) Jurisdiction of court"],[0,"Upon the filing of the record with it the jurisdiction of the court of appeals of the United States to affirm, enforce, modify, or set aside orders of the Commission shall be exclusive."],[0,"(e) Exemption from liability"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/45?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§45. Unfair methods of competition unlawful; prevention by Commission","tname":"Commerce and Trade","by":{"0":"39, 1, 4, 5, 32, 5, 32, 5, 32, passim, 2, 5, 27, 31, 32, 4, 32, 32","1":"4, 43, 1, 28, 5, 5, 5, passim, 8, 9, 28, 9, 28","2":"3, 3, 28, 4, 40, 41, 4, 40, 41, 7, 41","3":"20, 18, passim"}},{"t":"usc","label":"15 U.S.C. § 53","url":"https://www.law.cornell.edu/uscode/text/15/53","subs":["(b)","(a)","(b)(1)","(b)(2)"],"stext":{"head":"§53. False advertisements; injunctions and restraining orders","paras":[[0,"(a) Power of Commission; jurisdiction of courts"],[0,"Whenever the Commission has reason to believe—"],[1,"(1) that any person, partnership, or corporation is engaged in, or is about to engage in, the dissemination or the causing of the dissemination of any advertisement in violation of section 52 of this title, and"],[1,"(2) that the enjoining thereof pending the issuance of a complaint by the Commission under section 45 of this title, and until such complaint is dismissed by the Commission or set aside by the court on review, or the order of the Commission to cease and desist made thereon has become final within the meaning of section 45 of this title, would be to the interest of the public,"],[0,"the Commission by any of its attorneys designated by it for such purpose may bring suit in a district court of the United States or in the United States court of any Territory, to enjoin the dissemination or the causing of the dissemination of such advertisement. Upon proper showing a temporary injunction or restraining order shall be granted without bond. Any suit may be brought where such person, partnership, or corporation resides or transacts business, or wherever venue is proper under section 1391 of title 28. In addition, the court may, if the court determines that the interests of justice require that any other person, partnership, or corporation should be a party in such suit, cause such other person, partnership, or corporation to be added as a party without regard to whether venue is otherwise proper in the district in which the suit is brought. In any suit under this section, process may be served on any person, partnership, or corporation wherever it may be found."],[0,"(b) Temporary restraining orders; preliminary injunctions"],[0,"Whenever the Commission has reason to believe—"],[1,"(1) that any person, partnership, or corporation is violating, or is about to violate, any provision of law enforced by the Federal Trade Commission, and"],[1,"(2) that the enjoining thereof pending the issuance of a complaint by the Commission and until such complaint is dismissed by the Commission or set aside by the court on review, or until the order of the Commission made thereon has become final, would be in the interest of the public—"],[0,"the Commission by any of its attorneys designated by it for such purpose may bring suit in a district court of the United States to enjoin any such act or practice. Upon a proper showing that, weighing the equities and considering the Commission's likelihood of ultimate success, such action would be in the public interest, and after notice to the defendant, a temporary restraining order or a preliminary injunction may be granted without bond: Provided, however, That if a complaint is not filed within such period (not exceeding 20 days) as may be specified by the court after issuance of the temporary restraining order or preliminary injunction, the order or injunction shall be dissolved by the court and be of no further force and effect: Provided further, That in proper cases the Commission may seek, and after proper proof, the court may issue, a permanent injunction. Any suit may be brought where such person, partnership, or corporation resides or transacts business, or wherever venue is proper under section 1391 of title 28. In addition, the court may, if the court determines that the interests of justice require that any other person, partnership, or corporation should be a party in such suit, cause such other person, partnership, or corporation to be added as a party without regard to whether venue is otherwise proper in the district in which the suit is brought. In any suit under this section, process may be served on any person, partnership, or corporation wherever it may be found."],[0,"(c) Service of process; proof of service"],[0,"Any process of the Commission under this section may be served by any person duly authorized by the Commission—"],[1,"(1) by delivering a copy of such process to the person to be served, to a member of the partnership to be served, or to the president, secretary, or other executive officer or a director of the corporation to be served;"],[1,"(2) by leaving a copy of such process at the residence or the principal office or place of business of such person, partnership, or corporation; or"],[1,"(3) by mailing a copy of such process by registered mail or certified mail addressed to such person, partnership, or corporation at his, or her, or its residence, principal office, or principal place or business."],[0,"The verified return by the person serving such process setting forth the manner of such service shall be proof of the same."],[0,"(d) Exception of periodical publications"],[0,"Whenever it appears to the satisfaction of the court in the case of a newspaper, magazine, periodical, or other publication, published at regular intervals—"],[1,"(1) that restraining the dissemination of a false advertisement in any particular issue of such publication would delay the delivery of such issue after the regular time therefor, and"],[1,"(2) that such delay would be due to the method by which the manufacture and distribution of such publication is customarily conducted by the publisher in accordance with sound business practice, and not to any method or device adopted for the evasion of this section or to prevent or delay the issuance of an injunction or restraining order with respect to such false advertisement or any other advertisement,"],[0,"the court shall exclude such issue from the operation of the restraining order or injunction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/53?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§53. False advertisements; injunctions and restraining orders","tname":"Commerce and Trade","by":{"0":"passim","1":"40, passim, 28","2":"5, 26, 4, 5, 26, 41, 49","3":"passim, 16"}},{"t":"usc","label":"15 U.S.C. § 57a","url":"https://www.law.cornell.edu/uscode/text/15/57a","subs":["(a)(1)(B)","(b)(1)","(b)(2)(A)","(d)(1)","(d)"],"stext":{"head":"§57a. Unfair or deceptive acts or practices rulemaking proceedings","paras":[[0,"(a) Authority of Commission to prescribe rules and general statements of policy"],[0,"(1) Except as provided in subsection (h), the Commission may prescribe—"],[1,"(A) interpretive rules and general statements of policy with respect to unfair or deceptive acts or practices in or affecting commerce (within the meaning of section 45(a)(1) of this title), and"],[1,"(B) rules which define with specificity acts or practices which are unfair or deceptive acts or practices in or affecting commerce (within the meaning of section 45(a)(1) of this title), except that the Commission shall not develop or promulgate any trade rule or regulation with regard to the regulation of the development and utilization of the standards and certification activities pursuant to this section. Rules under this subparagraph may include requirements prescribed for the purpose of preventing such acts or practices."],[0,"(2) The Commission shall have no authority under this subchapter, other than its authority under this section, to prescribe any rule with respect to unfair or deceptive acts or practices in or affecting commerce (within the meaning of section 45(a)(1) of this title). The preceding sentence shall not affect any authority of the Commission to prescribe rules (including interpretive rules), and general statements of policy, with respect to unfair methods of competition in or affecting commerce."],[0,"(b) Procedures applicable"],[0,"(1) When prescribing a rule under subsection (a)(1)(B) of this section, the Commission shall proceed in accordance with section 553 of title 5 (without regard to any reference in such section to sections 556 and 557 of such title), and shall also (A) publish a notice of proposed rulemaking stating with particularity the text of the rule, including any alternatives, which the Commission proposes to promulgate, and the reason for the proposed rule; (B) allow interested persons to submit written data, views, and arguments, and make all such submissions publicly available; (C) provide an opportunity for an informal hearing in accordance with subsection (c); and (D) promulgate, if appropriate, a final rule based on the matter in the rulemaking record (as defined in subsection (e)(1)(B)), together with a statement of basis and purpose."],[0,"(2)(A) Prior to the publication of any notice of proposed rulemaking pursuant to paragraph (1)(A), the Commission shall publish an advance notice of proposed rulemaking in the Federal Register. Such advance notice shall—"],[1,"(i) contain a brief description of the area of inquiry under consideration, the objectives which the Commission seeks to achieve, and possible regulatory alternatives under consideration by the Commission; and"],[1,"(ii) invite the response of interested parties with respect to such proposed rulemaking, including any suggestions or alternative methods for achieving such objectives."],[0,"(B) The Commission shall submit such advance notice of proposed rulemaking to the Committee on Commerce, Science, and Transportation of the Senate and to the Committee on Energy and Commerce of the House of Representatives. The Commission may use such additional mechanisms as the Commission considers useful to obtain suggestions regarding the content of the area of inquiry before the publication of a general notice of proposed rulemaking under paragraph (1)(A)."],[0,"(C) The Commission shall, 30 days before the publication of a notice of proposed rulemaking pursuant to paragraph (1)(A), submit such notice to the Committee on Commerce, Science, and Transportation of the Senate and to the Committee on Energy and Commerce of the House of Representatives."],[0,"(3) The Commission shall issue a notice of proposed rulemaking pursuant to paragraph (1)(A) only where it has reason to believe that the unfair or deceptive acts or practices which are the subject of the proposed rulemaking are prevalent. The Commission shall make a determination that unfair or deceptive acts or practices are prevalent under this paragraph only if—"],[1,"(A) it has issued cease and desist orders regarding such acts or practices, or"],[1,"(B) any other information available to the Commission indicates a widespread pattern of unfair or deceptive acts or practices."],[0,"(c) Informal hearing procedure"],[0,"The Commission shall conduct any informal hearings required by subsection (b)(1)(C) of this section in accordance with the following procedure:"],[1,"(1)(A) The Commission shall provide for the conduct of proceedings under this subsection by hearing officers who shall perform their functions in accordance with the requirements of this subsection."],[1,"(B) The officer who presides over the rulemaking proceedings shall be responsible to a chief presiding officer who shall not be responsible to any other officer or employee of the Commission. The officer who presides over the rulemaking proceeding shall make a recommended decision based upon the findings and conclusions of such officer as to all relevant and material evidence, except that such recommended decision may be made by another officer if the officer who presided over the proceeding is no longer available to the Commission."],[1,"(C) Except as required for the disposition of ex parte matters as authorized by law, no presiding officer shall consult any person or party with respect to any fact in issue unless such officer gives notice and opportunity for all parties to participate."],[1,"(2) Subject to paragraph (3) of this subsection, an interested person is entitled—"],[2,"(A) to present his position orally or by documentary submission (or both), and"],[2,"(B) if the Commission determines that there are disputed issues of material fact it is necessary to resolve, to present such rebuttal submissions and to conduct (or have conducted under paragraph (3)(B)) such cross-examination of persons as the Commission determines (i) to be appropriate, and (ii) to be required for a full and true disclosure with respect to such issues."],[1,"(3) The Commission may prescribe such rules and make such rulings concerning proceedings in such hearings as may tend to avoid unnecessary costs or delay. Such rules or rulings may include (A) imposition of reasonable time limits on each interested person's oral presentations, and (B) requirements that any cross-examination to which a person may be entitled under paragraph (2) be conducted by the Commission on behalf of that person in such manner as the Commission determines (i) to be appropriate, and (ii) to be required for a full and true disclosure with respect to disputed issues of material fact."],[1,"(4)(A) Except as provided in subparagraph (B), if a group of persons each of whom under paragraphs (2) and (3) would be entitled to conduct (or have conducted) cross-examination and who are determined by the Commission to have the same or similar interests in the proceeding cannot agree upon a single representative of such interests for purposes of cross-examination, the Commission may make rules and rulings (i) limiting the representation of such interest, for such purposes, and (ii) governing the manner in which such cross-examination shall be limited."],[1,"(B) When any person who is a member of a group with respect to which the Commission has made a determination under subparagraph (A) is unable to agree upon group representation with the other members of the group, then such person shall not be denied under the authority of subparagraph (A) the opportunity to conduct (or have conducted) cross-examination as to issues affecting his particular interests if (i) he satisfies the Commission that he has made a reasonable and good faith effort to reach agreement upon group representation with the other members of the group and (ii) the Commission determines that there are substantial and relevant issues which are not adequately presented by the group representative."],[1,"(5) A verbatim transcript shall be taken of any oral presentation, and cross-examination, in an informal hearing to which this subsection applies. Such transcript shall be available to the public."],[0,"(d) Statement of basis and purpose accompanying rule; \"Commission\" defined; judicial review of amendment or repeal of rule; violation of rule"],[0,"(1) The Commission's statement of basis and purpose to accompany a rule promulgated under subsection (a)(1)(B) shall include (A) a statement as to the prevalence of the acts or practices treated by the rule; (B) a statement as to the manner and context in which such acts or practices are unfair or deceptive; and (C) a statement as to the economic effect of the rule, taking into account the effect on small business and consumers."],[0,"(2)(A) The term \"Commission\" as used in this subsection and subsections (b) and (c) includes any person authorized to act in behalf of the Commission in any part of the rulemaking proceeding."],[0,"(B) A substantive amendment to, or repeal of, a rule promulgated under subsection (a)(1)(B) shall be prescribed, and subject to judicial review, in the same manner as a rule prescribed under such subsection. An exemption under subsection (g) shall not be treated as an amendment or repeal of a rule."],[0,"(3) When any rule under subsection (a)(1)(B) takes effect a subsequent violation thereof shall constitute an unfair or deceptive act or practice in violation of section 45(a)(1) of this title, unless the Commission otherwise expressly provides in such rule."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/57a?type=usc&year=mostrecent&link-type=html"},"head":"§57a. Unfair or deceptive acts or practices rulemaking proceedings","tname":"Commerce and Trade","by":{"0":"4, 4, 4, 32, 4","1":"5, 6, 6","2":"7"}},{"t":"usc","label":"15 U.S.C. § 57b","url":"https://www.law.cornell.edu/uscode/text/15/57b","subs":["(a)","(a)(1)","(a)(2)","(b)","(d)","(e)","(c)(2)"],"stext":{"head":"§57b. Civil actions for violations of rules and cease and desist orders respecting unfair or deceptive acts or practices","paras":[[0,"(a) Suits by Commission against persons, partnerships, or corporations; jurisdiction; relief for dishonest or fraudulent acts"],[0,"(1) If any person, partnership, or corporation violates any rule under this subchapter respecting unfair or deceptive acts or practices (other than an interpretive rule, or a rule violation of which the Commission has provided is not an unfair or deceptive act or practice in violation of section 45(a) of this title), then the Commission may commence a civil action against such person, partnership, or corporation for relief under subsection (b) in a United States district court or in any court of competent jurisdiction of a State."],[0,"(2) If any person, partnership, or corporation engages in any unfair or deceptive act or practice (within the meaning of section 45(a)(1) of this title) with respect to which the Commission has issued a final cease and desist order which is applicable to such person, partnership, or corporation, then the Commission may commence a civil action against such person, partnership, or corporation in a United States district court or in any court of competent jurisdiction of a State. If the Commission satisfies the court that the act or practice to which the cease and desist order relates is one which a reasonable man would have known under the circumstances was dishonest or fraudulent, the court may grant relief under subsection (b)."],[0,"(b) Nature of relief available"],[0,"The court in an action under subsection (a) shall have jurisdiction to grant such relief as the court finds necessary to redress injury to consumers or other persons, partnerships, and corporations resulting from the rule violation or the unfair or deceptive act or practice, as the case may be. Such relief may include, but shall not be limited to, rescission or reformation of contracts, the refund of money or return of property, the payment of damages, and public notification respecting the rule violation or the unfair or deceptive act or practice, as the case may be; except that nothing in this subsection is intended to authorize the imposition of any exemplary or punitive damages."],[0,"(c) Conclusiveness of findings of Commission in cease and desist proceedings; notice of judicial proceedings to injured persons, etc."],[0,"(1) If (A) a cease and desist order issued under section 45(b) of this title has become final under section 45(g) of this title with respect to any person's, partnership's, or corporation's rule violation or unfair or deceptive act or practice, and (B) an action under this section is brought with respect to such person's, partnership's, or corporation's rule violation or act or practice, then the findings of the Commission as to the material facts in the proceeding under section 45(b) of this title with respect to such person's, partnership's, or corporation's rule violation or act or practice, shall be conclusive unless (i) the terms of such cease and desist order expressly provide that the Commission's findings shall not be conclusive, or (ii) the order became final by reason of section 45(g)(1) of this title, in which case such finding shall be conclusive if supported by evidence."],[0,"(2) The court shall cause notice of an action under this section to be given in a manner which is reasonably calculated, under all of the circumstances, to apprise the persons, partnerships, and corporations allegedly injured by the defendant's rule violation or act or practice of the pendency of such action. Such notice may, in the discretion of the court, be given by publication."],[0,"(d) Time for bringing of actions"],[0,"No action may be brought by the Commission under this section more than 3 years after the rule violation to which an action under subsection (a)(1) relates, or the unfair or deceptive act or practice to which an action under subsection (a)(2) relates; except that if a cease and desist order with respect to any person's, partnership's, or corporation's rule violation or unfair or deceptive act or practice has become final and such order was issued in a proceeding under section 45(b) of this title which was commenced not later than 3 years after the rule violation or act or practice occurred, a civil action may be commenced under this section against such person, partnership, or corporation at any time before the expiration of one year after such order becomes final."],[0,"(e) Availability of additional Federal or State remedies; other authority of Commission unaffected"],[0,"Remedies provided in this section are in addition to, and not in lieu of, any other remedy or right of action provided by State or Federal law. Nothing in this section shall be construed to affect any authority of the Commission under any other provision of law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/57b?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§57b. Civil actions for violations of rules and cease and desist orders respecting unfair or deceptive acts or practices","tname":"Commerce and Trade","by":{"0":"2, 11, 32, 5, 6, passim, passim, 30","1":"8, 2, 8, 27, 29, 8, 27, 29, 42, passim, 8, 29, 31, 32","2":"7, 43, 6, 41, 44, 7, 41, 7, 44, 7, 15, 39, 45, 46","3":"passim, 18, 15, 19, 3, 15, 17, 21, 15, 15, 19"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","subs":["(d)(1)","(d)(5)"],"stext":{"head":"§78u. Investigations and actions","paras":[[0,"(a) Authority and discretion of Commission to investigate violations"],[0,"(1) The Commission may, in its discretion, make such investigations as it deems necessary to determine whether any person has violated, is violating, or is about to violate any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated, or, as to any act or practice, or omission to act, while associated with a member, formerly associated with a member, the rules of a registered clearing agency in which such person is a participant, or, as to any act or practice, or omission to act, while a participant, was a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm, a person associated with such a firm, or, as to any act, practice, or omission to act, while associated with such firm, a person formerly associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, and may require or permit any person to file with it a statement in writing, under oath or otherwise as the Commission shall determine, as to all the facts and circumstances concerning the matter to be investigated. The Commission is authorized in its discretion, to publish information concerning any such violations, and to investigate any facts, conditions, practices, or matters which it may deem necessary or proper to aid in the enforcement of such provisions, in the prescribing of rules and regulations under this chapter, or in securing information to serve as a basis for recommending further legislation concerning the matters to which this chapter relates."],[0,"(2) On request from a foreign securities authority, the Commission may provide assistance in accordance with this paragraph if the requesting authority states that the requesting authority is conducting an investigation which it deems necessary to determine whether any person has violated, is violating, or is about to violate any laws or rules relating to securities matters that the requesting authority administers or enforces. The Commission may, in its discretion, conduct such investigation as the Commission deems necessary to collect information and evidence pertinent to the request for assistance. Such assistance may be provided without regard to whether the facts stated in the request would also constitute a violation of the laws of the United States. In deciding whether to provide such assistance, the Commission shall consider whether (A) the requesting authority has agreed to provide reciprocal assistance in securities matters to the Commission; and (B) compliance with the request would prejudice the public interest of the United States."],[0,"(b) Attendance of witnesses; production of records"],[0,"For the purpose of any such investigation, or any other proceeding under this chapter, any member of the Commission or any officer designated by it is empowered to administer oaths and affirmations, subpena witnesses, compel their attendance, take evidence, and require the production of any books, papers, correspondence, memoranda, or other records which the Commission deems relevant or material to the inquiry. Such attendance of witnesses and the production of any such records may be required from any place in the United States or any State at any designated place of hearing."],[0,"(c) Judicial enforcement of investigative power of Commission; refusal to obey subpena; criminal sanctions"],[0,"In case of contumacy by, or refusal to obey a subpena issued to, any person, the Commission may invoke the aid of any court of the United States within the jurisdiction of which such investigation or proceeding is carried on, or where such person resides or carries on business, in requiring the attendance and testimony of witnesses and the production of books, papers, correspondence, memoranda, and other records. And such court may issue an order requiring such person to appear before the Commission or member or officer designated by the Commission, there to produce records, if so ordered, or to give testimony touching the matter under investigation or in question; and any failure to obey such order of the court may be punished by such court as a contempt thereof. All process in any such case may be served in the judicial district whereof such person is an inhabitant or wherever he may be found. Any person who shall, without just cause, fail or refuse to attend and testify or to answer any lawful inquiry or to produce books, papers, correspondence, memoranda, and other records, if in his power so to do, in obedience to the subpena of the Commission, shall be guilty of a misdemeanor and, upon conviction, shall be subject to a fine of not more than $1,000 or to imprisonment for a term of not more than one year, or both."],[0,"(d) Injunction proceedings; authority of court to prohibit persons from serving as officers and directors; money penalties in civil actions; disgorgement"],[0,"(1) Whenever it shall appear to the Commission that any person is engaged or is about to engage in acts or practices constituting a violation of any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated with a member, the rules of a registered clearing agency in which such person is a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm or a person associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, it may in its discretion bring an action in the proper district court of the United States, the United States District Court for the District of Columbia, or the United States courts of any territory or other place subject to the jurisdiction of the United States, to enjoin such acts or practices, and upon a proper showing a permanent or temporary injunction or restraining order shall be granted without bond. The Commission may transmit such evidence as may be available concerning such acts or practices as may constitute a violation of any provision of this chapter or the rules or regulations thereunder to the Attorney General, who may, in his discretion, institute the necessary criminal proceedings under this chapter."],[0,"(2) Authority of Court To Prohibit Persons From Serving as Officers and Directors.—In any proceeding under paragraph (1) of this subsection, the court may prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who violated section 78j(b) of this title or the rules or regulations thereunder from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title or that is required to file reports pursuant to section 78o(d) of this title if the person's conduct demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(3) Civil money penalties and authority to seek disgorgement.—"],[1,"(A) Authority of commission.—Whenever it shall appear to the Commission that any person has violated any provision of this chapter, the rules or regulations thereunder, or a cease-and-desist order entered by the Commission pursuant to section 78u–3 of this title, other than by committing a violation subject to a penalty pursuant to section 78u–1 of this title, the Commission may bring an action in a United States district court to seek, and the court shall have jurisdiction to—"],[2,"(i) impose, upon a proper showing, a civil penalty to be paid by the person who committed such violation; and"],[2,"(ii) require disgorgement under paragraph (7) of any unjust enrichment by the person who received such unjust enrichment as a result of such violation."],[1,"(B) Amount of penalty.—"],[2,"(i) First tier.—The amount of a civil penalty imposed under subparagraph (A)(i) shall be determined by the court in light of the facts and circumstances. For each violation, the amount of the penalty shall not exceed the greater of (I) $5,000 for a natural person or $50,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation."],[2,"(ii) Second tier.—Notwithstanding clause (i), the amount of a civil penalty imposed under subparagraph (A)(i) for each such violation shall not exceed the greater of (I) $50,000 for a natural person or $250,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if the violation described in subparagraph (A) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[2,"(iii) Third tier.—Notwithstanding clauses (i) and (ii), the amount of a civil penalty imposed under subparagraph (A)(i) for each violation described in that subparagraph shall not exceed the greater of (I) $100,000 for a natural person or $500,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u?type=usc&year=mostrecent&link-type=html"},"head":"§78u. Investigations and actions","tname":"Commerce and Trade","by":{"0":"29, 29","1":"41, 45, 46","2":"26, 26"}},{"t":"usc","label":"15 U.S.C. § 1116","url":"https://www.law.cornell.edu/uscode/text/15/1116","subs":["(a)"],"by":{"0":"29"}},{"t":"usc","label":"15 U.S.C. § 1117","url":"https://www.law.cornell.edu/uscode/text/15/1117","subs":["(a)"],"by":{"0":"30"}},{"t":"usc","label":"15 U.S.C. § 3414","url":"https://www.law.cornell.edu/uscode/text/15/3414","subs":["(b)(4)"],"stext":{"head":"§3414. Enforcement","paras":[[0,"(a) General rule"],[0,"It shall be unlawful for any person to violate any provision of this chapter or any rule or order under this chapter."],[0,"(b) Civil enforcement"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), whenever it appears to the Commission that any person is engaged or about to engage in any act or practice which constitutes or will constitute a violation of any provision of this chapter, or of any rule or order thereunder, the Commission may bring an action in the District Court of the United States for the District of Columbia or any other appropriate district court of the United States to enjoin such act or practice and to enforce compliance with this chapter, or any rule or order thereunder."],[0,"(2) Enforcement of emergency orders"],[1,"Whenever it appears to the President that any person has engaged, is engaged, or is about to engage in acts or practices constituting a violation of any order under section 3362 of this title or any order or supplemental order issued under section 3363 of this title, the President may bring a civil action in any appropriate district court of the United States to enjoin such acts or practices."],[0,"(3) Repealed. Pub. L. 101–60, §3(a)(4)(B), July 26, 1989, 103 Stat. 158"],[0,"(4) Relief available"],[1,"In any action under paragraph (1) or (2), the court shall, upon a proper showing, issue a temporary restraining order or preliminary or permanent injunction without bond. In any such action, the court may also issue a mandatory injunction commanding any person to comply with any applicable provision of law, rule, or order, or ordering such other legal or equitable relief as the court determines appropriate, including refund or restitution."],[0,"(5) Criminal referral"],[1,"The Commission may transmit such evidence as may be available concerning any acts or practices constituting any possible violations of the Federal antitrust laws to the Attorney General who may institute appropriate criminal proceedings."],[0,"(6) Civil penalties"],[0,"(A) In general"],[2,"Any person who knowingly violates any provision of this chapter, or any provision of any rule or order under this chapter, shall be subject to—"],[3,"(i) except as provided in clause (ii) a civil penalty, which the Commission may assess, of not more than $1,000,000 for any one violation; and"],[3,"(ii) a civil penalty, which the President may assess, of not more than $1,000,000, in the case of any violation of an order under section 3362 of this title or an order or supplemental order under section 3363 of this title."],[0,"(B) \"Knowing\" defined"],[2,"For purposes of subparagraph (A) the term \"knowing\" means the having of—"],[3,"(i) actual knowledge; or"],[3,"(ii) the constructive knowledge deemed to be possessed by a reasonable individual who acts under similar circumstances."],[0,"(C) Each day separate violation"],[2,"For purposes of this paragraph, in the case of a continuing violation, each day of violation shall constitute a separate violation."],[0,"(D) Statute of limitations"],[2,"No person shall be subject to any civil penalty under this paragraph with respect to any violation occurring more than 3 years before the date on which such person is provided notice of the proposed penalty under subparagraph (E). The preceding sentence shall not apply in any case in which an untrue statement of material fact was made to the Commission or a State or Federal agency by, or acquiesced to by, the violator with respect to the acts or omissions constituting such violation, or if there was omitted a material fact necessary in order to make any statement made by, or acquiesced to by, the violator with respect to such acts or omissions not misleading in light of circumstances under such statement was made."],[0,"(E) Assessed by Commission"],[2,"Before assessing any civil penalty under this paragraph, the Commission shall provide to such person notice of the proposed penalty. Following receipt of notice of the proposed penalty by such person, the Commission shall, by order, asssess 1 such penalty."],[0,"(F) Judicial review"],[2,"If the civil penalty has not been paid within 60 calendar days after the assessment order has been made under subparagraph (E), the Commission shall institute an action in the appropriate district court of the United States for an order affirming the assessment of the civil penalty. The court shall have authority to review de novo the law and the facts involved, and shall have jurisdiction to enter a judgment enforcing, modifying, and enforcing as so modified, or setting aside in whole or in part, such assessment."],[0,"(c) Criminal penalties"],[0,"(1) Violations of chapter"],[1,"Except in the case of violations covered under paragraph (3), any person who knowingly and willfully violates any provision of this chapter shall be subject to—"],[2,"(A) a fine of not more than $1,000,000; or"],[2,"(B) imprisonment for not more than 5 years; or"],[2,"(C) both such fine and such imprisonment."],[0,"(2) Violation of rules or orders generally"],[1,"Except in the case of violations covered under paragraph (3), any person who knowingly and willfully violates any rule or order under this chapter (other than an order of the Commission assessing a civil penalty under subsection (b)(4)(E)), shall be subject to a fine of not more than $50,000 for each day on which the offense occurs."],[0,"(3) Violations of emergency orders"],[1,"Any person who knowingly and willfully violates an order under section 3362 of this title or an order or supplemental order under section 3363 of this title shall be fined not more than $50,000 for each violation."],[0,"(4) Each day separate violation"],[1,"For purposes of this subsection, each day of violation shall constitute a separate violation."],[0,"(5) \"Knowingly\" defined"],[1,"For purposes of this subsection, the term \"knowingly\", when used with respect to any act or omission by any person, means such person—"],[2,"(A) had actual knowledge; or"],[2,"(B) had constructive knowledge deemed to be possessed by a reasonable individual who acts under similar circumstances."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/3414?type=usc&year=mostrecent&link-type=html"},"head":"§3414. Enforcement","tname":"Commerce and Trade","by":{"0":"30","1":"21"}},{"t":"usc","label":"12 U.S.C. § 5531","url":"https://www.law.cornell.edu/uscode/text/12/5531","subs":["(a)"],"by":{"0":"42"}},{"t":"usc","label":"12 U.S.C. § 5564","url":"https://www.law.cornell.edu/uscode/text/12/5564","subs":["(a)"],"by":{"0":"29"}},{"t":"usc","label":"17 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/17/502","subs":["(a)"],"by":{"0":"28"}},{"t":"usc","label":"17 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/17/504","by":{"0":"28"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"3","1":"3"}},{"t":"usc","label":"28 U.S.C. § 2462","url":"https://www.law.cornell.edu/uscode/text/28/2462","by":{"0":"34, 42"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)","(a)(8)"],"by":{"0":"29, 29"}},{"t":"usc","label":"38 U.S.C. § 4323","url":"https://www.law.cornell.edu/uscode/text/38/4323","subs":["(e)"],"by":{"0":"29"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(g)(1)"],"by":{"0":"29"}},{"t":"reg","label":"Withdrawal of the Comm’n Policy Statement on Monetary Equitable Remedies in Competition Cases, 77 Fed. Reg. 47,070","url":"https://www.govinfo.gov/link/fr/77/47070","by":{"0":"39"}},{"t":"case","label":"Adams Express Co. v. Croninger","cite":"226 U.S. 491","y":1913,"id":"scdb/1912-053","sc":1,"sum":"The constitutional power of Congress to regulate commerce among the States and with foreign nations comprehends power to regulate contracts between shipperand carrier of shipments in such eom-. merce in regard to liability for loss or damage to articles carried.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Am. Tel. & Tel. Co. v. Cent. Off. Tel., Inc.","cite":"524 U.S. 214","y":1998,"id":"1997/97-679","sc":1,"sum":"The Court held that Communications Act's filed-tariff requirements pre-empt Central Office Telephone, Inc.'s state-law claims.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Arrow-Hart & Hegeman Elec. Co. v. FTC","cite":"291 U.S. 587","y":1934,"id":"scdb/1933-100","sc":1,"sum":"After commencement of a proceeding by the Federal Trade Commission to compel a holding company to divest itself of the voting stock of two competing operating companies, held by it in alleged violation of the Clayton Act, a reorganization was brought about through united participation of the owners of the holding company's shares and of the preferred stock of the operating companies, which the holding company never …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 44","3":"8"}},{"t":"case","label":"Atl. Refin. Co. v. FTC","cite":"381 U.S. 357","y":1965,"id":"1964/292","sc":1,"sum":"The Atlantic Refining Co., a major producer and distributor of gasoline and oil products on the eastern seaboard, agreed with the Goodyear Tire & Rubber Co., the country's largest manufacturer of rubber products, to sponsor the sale of the latter's tires, batteries and accessories (TBA) to its many retail service station dealers and wholesale outlets. Atlantic was primarily respbnsible for promoting the sale of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Block v. Cmty. Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"City of Rancho Palos Verdes v. Abrams","cite":"544 U.S. 113","y":2005,"id":"2004/03-1601","sc":1,"sum":"The Court held that Abrams could not enforce the limitations of the Telecommunications Act on local authorities through federal liability law, because the act provides its own judicial remedy. Congress could not have meant the judicial remedy expressly authorized by the Telecommunications Act to co-exist with an alternative remedy.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Dombrowski v. Pfister","cite":"380 U.S. 479","y":1965,"id":"1964/52","sc":1,"sum":"Appellants, a civil rights organization and its executive director, brought suit in Federal District Court, in which other individuals later joined, for injunctive and declaratory relief to restrain appellees from prosecuting or threatening to prosecute them under Louisiana's Subversive Activities and Communist Control Law and Communist Propaganda Control Law, which they alleged violated their rights of free …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22","2":"31"}},{"t":"case","label":"Edelman v. Jordan","cite":"415 U.S. 651","y":1974,"id":"1973/72-1410","sc":1,"sum":"The Eleventh Amendment of the Constitution bars that portion of the District Court's decree that ordered retroactive pavment of benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"30","2":"39"}},{"t":"case","label":"FTC v. Brown Shoe Co.","cite":"384 U.S. 316","y":1966,"id":"1965/118","sc":1,"sum":"The FTC acted well within its authority under the Act in declaring respondent's franchise program an unfair, trade practice.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 27"}},{"t":"case","label":"FTC v. Cement Inst.","cite":"333 U.S. 683","y":1948,"id":"scdb/1947-067","sc":1,"sum":"L The Commission has jurisdiction to conclude that conduct tending to restrain trade is an unfair method of competition viola-tive of § 5 of the Federal Trade Commission Act, even though the selfsame conduct may also violate the Sherman Act. Pp. 689-693. Cement Co. et al.; No. 25, Federal Trade Comm'n v. Marquette Cement Mig. Co.; No. 26, Federal Trade Comm'n v. Calaveras Cement Co. et al..N;o. 27, Federal Trade …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 27, 43"}},{"t":"case","label":"FTC v. Credit Bureau Ctr., LLC","cite":"937 F.3d 764","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/937/764/","op":1,"by":{"1":"passim","2":"8, 28","3":"15, 20"}},{"t":"case","label":"FTC v. Direct Mktg. Concepts, Inc.","cite":"624 F.3d 1","y":2010,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/624/1/","by":{"1":"10","2":"8"}},{"t":"case","label":"FTC v. Freecom Commc’ns, Inc.","cite":"401 F.3d 1192","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/401/1192/","by":{"1":"10","2":"8, 28"}},{"t":"case","label":"FTC v. Gem Merch. Corp.","cite":"87 F.3d 466","y":1996,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/87/466/","by":{"1":"10, 33","2":"28"}},{"t":"case","label":"FTC v. Gratz","cite":"253 U.S. 421","y":1920,"id":"scdb/1919-044","sc":1,"sum":"Under the Federal Trade Commission Act (Sépt. 26, 1914, c. 311, 38. Stat. 717), an order of the commission requiring parties to desist from a course of business as unfair competition must correspond with the complaint which the commission is required to issue and serve as the basis for the proceedings; and where the complaint, liberally-construed, is plainly insufficient to show unfair competition, the order is …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"5"}},{"t":"case","label":"FTC v. H. N. Singer, Inc.","cite":"668 F.2d 1107","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/668/1107/","op":1,"by":{"1":"10, 12","2":"8, 27"}},{"t":"case","label":"FTC v. Motion Picture Advert. Serv. Co.","cite":"344 U.S. 392","y":1953,"id":"scdb/1952-039","sc":1,"sum":"The order is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5"}},{"t":"case","label":"FTC v. Ross","cite":"743 F.3d 886","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/743/886/","by":{"1":"2, 10, 33, 36","2":"8"}},{"t":"case","label":"FTC v. Sec. Rare Coin & Bullion Corp.","cite":"931 F.2d 1312","y":1991,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/931/1312/","by":{"1":"10, 33","2":"8, 27"}},{"t":"case","label":"FTC v. Shire Viropharma, Inc.","cite":"917 F.3d 147","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/917/147/","by":{"1":"25"}},{"t":"case","label":"\u0003 \u0003 FTC v. Stefanchik","cite":"559 F.3d 924","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/559/924/","by":{"1":"47"}},{"t":"case","label":"Grupo Mexicano de Desarrollo, S.A. v. All. Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Hardin v. Straub","cite":"490 U.S. 536","y":1989,"id":"1988/87-7023","sc":1,"sum":"A federal court applying a state statute of limitations to an inmate's federal civil rights action should give effect to the State's provision tolling the limitations period for prisoners. The Court of Appeals' ruling to the contrary conflicts with Board of Regents, University of New York v. Tomanio, 446 U. S. 478, which held that limitations periods in § 1983 suits are to be determined by reference to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Hardt v. Reliance Standard Life Ins. Co.","cite":"560 U.S. 242","y":2010,"id":"2009/09-448","sc":1,"sum":"The Court held that a party is entitled to attorneys' fees pursuant to Section 502(g)(1) of the Employee Retirement Income Security Act when an ERISA violation has occurred.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Humphrey’s Ex’r v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"1":"3","3":"22"}},{"t":"case","label":"Int’l Ass’n of Machinists v. Street","cite":"367 U.S. 740","y":1961,"id":"1959/4","sc":1,"sum":"The Supreme Court held that the lower court did not need to decide the constitutionality of the union shop agreement. The Court remanded the case with suggestions for possible remedies. Justice William O. Douglas wrote a concurrence noting reservations about the suggested remedies. Justice Charles E. Whitaker concurred in part, but dissented to the suggestion of remedies.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"1":"20, 26"}},{"t":"case","label":"J.I. Case Co. v. Borak","cite":"377 U.S. 426","y":1964,"id":"1963/402","sc":1,"ar":1,"sum":"Respondent, stockholder of petitioner company, brought a civil action in federal court for deprivation of his and other stockholders' preemptive rights by reason of a merger involving the company, allegedly effected through use of a false and misleading proxy statement. The complaint has two counts, one based on diversity and claiming a breach of directors' fiduciary duty to stockholders and the other alleging a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Kansas v. Nebraska","cite":"574 U.S. 445","y":2015,"id":"2014/126-orig","sc":1,"sum":"The Court ruled that Nebraska violated a compact apportioning the water resources of the Republican River among Kansas, Nebraska and Colorado.","sumSrc":"Oyez","by":{"1":"22","2":"12, 20, 37","3":"23"}},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Middlesex Cnty. Sewage Auth. v. Nat’l Sea Clammers Ass’n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"sum":"Respondents (an organization whose members harvest fish and shellfish off the coast of New York and New Jersey and one individual member) brought suit in Federal District Court against petitioners (various governmental entities and officials from New York, New Jersey, and the Federal Government), alleging damage to fishing grounds caused by discharges and ocean dumping of sewage and other waste. Invoking a number of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 32","2":"47"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"465 U.S. 89","y":1984,"id":"1982/81-2101","sc":1,"sum":"The Eleventh Amendment prohibited the District Court from ordering state officials to conform their conduct to state law.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Pub. Serv. Comm’n v. Wycoff Co.","cite":"344 U.S. 237","y":1952,"id":"scdb/1952-028","sc":1,"sum":"The suit cannot be entertained as one for injunction and should not be continued as one for a-declaratory judgment. Pp. 239-249.' 1. There can.be no injunction on constitutional grounds in this case. It is wanting in equity because there is no proof of any threatened or probable act of the defendants which might cause the irreparable injury essential to equitable relief by injunction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"140 S. Ct. 1492","y":2020,"id":"2019/18-1233","sc":1,"sum":"The Court held that under Section 35 of the Lanham Act, a plaintiff does not need to show willful infringement to receive an award of an infringer’s profits for a violation of Section 43(a).","sumSrc":"Oyez","by":{"1":"21, 25"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"42","3":"24"}},{"t":"case","label":"Swift & Co. v. United States","cite":"276 U.S. 311","y":1928,"id":"scdb/1927-141","sc":1,"sum":"1. Where a consent decree, entered in a suit brought by the Government under the Anti-Trust Act, provided for entertaining at any time thereafter any application which the parties might make in respect to it, motions to vacate it made by defendants four years later in response to petitions of intervention and entitled in the suit, were part of the original cause.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22","2":"31"}},{"t":"case","label":"Virginian Ry. Co. v. Sys. Fed’n No. 40","cite":"300 U.S. 515","y":1937,"id":"scdb/1936-092","sc":1,"sum":"(1) That the duty to \"treat\" with the representative so certified is mandatory. P. 547. (2) The statute does not undertake to compel agreement and does not preclude the employer from entering into individual contracts directly with individual employees, but it requires the employer to \"treat with\" the authorized representative of the employees, -that is, to meet and confer with their representative, to listen to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Warth v. Seldin","cite":"422 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"sum":"Whether the rules of standing are considered as aspects of the constitutional requirement that a plaintiff must make out a \"case or controversy\" within the meaning of Art. III, or, apart from such requirement, as prudential limitations on the courts' role in resolving disputes involving \"generalized grievances\" or third parties' legal rights or interests, none of the petitioners has met the threshold requirement of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22, 25","2":"31","3":"11"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"137 S. Ct. 1843","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"1":"36, 37","2":"13, 35","3":"12"}},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"1":"24"}},{"t":"usc","label":"15 U.S.C. § 56","url":"https://www.law.cornell.edu/uscode/text/15/56","subs":["(a)"],"by":{"1":"7, 8, 7"}},{"t":"usc","label":"7 U.S.C. § 13a-1","url":"https://www.law.cornell.edu/uscode/text/7/13a-1","subs":["(b)","(d)(3)"],"by":{"1":"21, 21"}},{"t":"usc","label":"15 U.S.C. § 21","url":"https://www.law.cornell.edu/uscode/text/15/21","subs":["(a)"],"by":{"1":"32"}},{"t":"usc","label":"15 U.S.C. § 6103","url":"https://www.law.cornell.edu/uscode/text/15/6103","subs":["(a)"],"by":{"1":"21"}},{"t":"usc","label":"29 U.S.C. § 217","url":"https://www.law.cornell.edu/uscode/text/29/217","stext":{"head":"§217. Injunction proceedings","paras":[[0,"The district courts, together with the United States District Court for the District of the Canal Zone, the District Court of the Virgin Islands, and the District Court of Guam shall have jurisdiction, for cause shown, to restrain violations of section 215 of this title, including in the case of violations of section 215(a)(2) of this title the restraint of any withholding of payment of minimum wages or overtime compensation found by the court to be due to employees under this chapter (except sums which employees are barred from recovering, at the time of the commencement of the action to restrain the violations, by virtue of the provisions of section 255 of this title)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/217?type=usc&year=mostrecent&link-type=html"},"head":"§217. Injunction proceedings","tname":"Labor","by":{"1":"35","2":"24"}},{"t":"usc","label":"42 U.S.C. § 6972","url":"https://www.law.cornell.edu/uscode/text/42/6972","subs":["(a)"],"stext":{"head":"§6972. Citizen suits","paras":[[0,"(a) In general"],[0,"Except as provided in subsection (b) or (c) of this section, any person may commence a civil action on his own behalf—"],[1,"(1)(A) against any person (including (a) the United States, and (b) any other governmental instrumentality or agency, to the extent permitted by the eleventh amendment to the Constitution) who is alleged to be in violation of any permit, standard, regulation, condition, requirement, prohibition, or order which has become effective pursuant to this chapter; or"],[1,"(B) against any person, including the United States and any other governmental instrumentality or agency, to the extent permitted by the eleventh amendment to the Constitution, and including any past or present generator, past or present transporter, or past or present owner or operator of a treatment, storage, or disposal facility, who has contributed or who is contributing to the past or present handling, storage, treatment, transportation, or disposal of any solid or hazardous waste which may present an imminent and substantial endangerment to health or the environment; or"],[1,"(2) against the Administrator where there is alleged a failure of the Administrator to perform any act or duty under this chapter which is not discretionary with the Administrator."],[0,"Any action under paragraph (a)(1) of this subsection shall be brought in the district court for the district in which the alleged violation occurred or the alleged endangerment may occur. Any action brought under paragraph (a)(2) of this subsection may be brought in the district court for the district in which the alleged violation occurred or in the District Court of the District of Columbia. The district court shall have jurisdiction, without regard to the amount in controversy or the citizenship of the parties, to enforce the permit, standard, regulation, condition, requirement, prohibition, or order, referred to in paragraph (1)(A), to restrain any person who has contributed or who is contributing to the past or present handling, storage, treatment, transportation, or disposal of any solid or hazardous waste referred to in paragraph (1)(B), to order such person to take such other action as may be necessary, or both, or to order the Administrator to perform the act or duty referred to in paragraph (2), as the case may be, and to apply any appropriate civil penalties under section 6928(a) and (g) of this title."],[0,"(b) Actions prohibited"],[0,"(1) No action may be commenced under subsection (a)(1)(A) of this section—"],[1,"(A) prior to 60 days after the plaintiff has given notice of the violation to—"],[2,"(i) the Administrator;"],[2,"(ii) the State in which the alleged violation occurs; and"],[2,"(iii) to any alleged violator of such permit, standard, regulation, condition, requirement, prohibition, or order,"],[1,"except that such action may be brought immediately after such notification in the case of an action under this section respecting a violation of subchapter III of this chapter; or"],[1,"(B) if the Administrator or State has commenced and is diligently prosecuting a civil or criminal action in a court of the United States or a State to require compliance with such permit, standard, regulation, condition, requirement, prohibition, or order."],[0,"In any action under subsection (a)(1)(A) in a court of the United States, any person may intervene as a matter of right."],[0,"(2)(A) No action may be commenced under subsection (a)(1)(B) of this section prior to ninety days after the plaintiff has given notice of the endangerment to—"],[1,"(i) the Administrator;"],[1,"(ii) the State in which the alleged endangerment may occur;"],[1,"(iii) any person alleged to have contributed or to be contributing to the past or present handling, storage, treatment, transportation, or disposal of any solid or hazardous waste referred to in subsection (a)(1)(B),"],[0,"except that such action may be brought immediately after such notification in the case of an action under this section respecting a violation of subchapter III of this chapter."],[0,"(B) No action may be commenced under subsection (a)(1)(B) of this section if the Administrator, in order to restrain or abate acts or conditions which may have contributed or are contributing to the activities which may present the alleged endangerment—"],[1,"(i) has commenced and is diligently prosecuting an action under section 6973 of this title or under section 106 of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 [42 U.S.C. 9606],1"],[1,"(ii) is actually engaging in a removal action under section 104 of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 [42 U.S.C. 9604];"],[1,"(iii) has incurred costs to initiate a Remedial Investigation and Feasibility Study under section 104 of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 [42 U.S.C. 9604] and is diligently proceeding with a remedial action under that Act [42 U.S.C. 9601 et seq.]; or"],[1,"(iv) has obtained a court order (including a consent decree) or issued an administrative order under section 106 of the Comprehensive Environmental Response, Compensation and Liability Act of 980 2 [42 U.S.C. 9606] or section 6973 of this title pursuant to which a responsible party is diligently conducting a removal action, Remedial Investigation and Feasibility Study (RIFS), or proceeding with a remedial action."],[0,"In the case of an administrative order referred to in clause (iv), actions under subsection (a)(1)(B) are prohibited only as to the scope and duration of the administrative order referred to in clause (iv)."],[0,"(C) No action may be commenced under subsection (a)(1)(B) of this section if the State, in order to restrain or abate acts or conditions which may have contributed or are contributing to the activities which may present the alleged endangerment—"],[1,"(i) has commenced and is diligently prosecuting an action under subsection (a)(1)(B);"],[1,"(ii) is actually engaging in a removal action under section 104 of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 [42 U.S.C. 9604]; or"],[1,"(iii) has incurred costs to initiate a Remedial Investigation and Feasibility Study under section 104 of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 [42 U.S.C. 9604] and is diligently proceeding with a remedial action under that Act [42 U.S.C. 9601 et seq.]."],[0,"(D) No action may be commenced under subsection (a)(1)(B) by any person (other than a State or local government) with respect to the siting of a hazardous waste treatment, storage, or a disposal facility, nor to restrain or enjoin the issuance of a permit for such facility."],[0,"(E) In any action under subsection (a)(1)(B) in a court of the United States, any person may intervene as a matter of right when the applicant claims an interest relating to the subject of the action and he is so situated that the disposition of the action may, as a practical matter, impair or impede his ability to protect that interest, unless the Administrator or the State shows that the applicant's interest is adequately represented by existing parties."],[0,"(F) Whenever any action is brought under subsection (a)(1)(B) in a court of the United States, the plaintiff shall serve a copy of the complaint on the Attorney General of the United States and with the Administrator."],[0,"(c) Notice"],[0,"No action may be commenced under paragraph (a)(2) of this section prior to sixty days after the plaintiff has given notice to the Administrator that he will commence such action, except that such action may be brought immediately after such notification in the case of an action under this section respecting a violation of subchapter III. Notice under this subsection shall be given in such manner as the Administrator shall prescribe by regulation. Any action respecting a violation under this chapter may be brought under this section only in the judicial district in which such alleged violation occurs."],[0,"(d) Intervention"],[0,"In any action under this section the Administrator, if not a party, may intervene as a matter of right."],[0,"(e) Costs"],[0,"The court, in issuing any final order in any action brought pursuant to this section or section 6976 of this title, may award costs of litigation (including reasonable attorney and expert witness fees) to the prevailing or substantially prevailing party, whenever the court determines such an award is appropriate. The court may, if a temporary restraining order or preliminary injunction is sought, require the filing of a bond or equivalent security in accordance with the Federal Rules of Civil Procedure."],[0,"(f) Other rights preserved"],[0,"Nothing in this section shall restrict any right which any person (or class of persons) may have under any statute or common law to seek enforcement of any standard or requirement relating to the management of solid waste or hazardous waste, or to seek any other relief (including relief against the Administrator or a State agency)."],[0,"(g) Transporters"],[0,"A transporter shall not be deemed to have contributed or to be contributing to the handling, storage, treatment, or disposal, referred to in subsection (a)(1)(B) taking place after such solid waste or hazardous waste has left the possession or control of such transporter, if the transportation of such waste was under a sole contractual arrangement arising from a published tariff and acceptance for carriage by common carrier by rail and such transporter has exercised due care in the past or present handling, storage, treatment, transportation and disposal of such waste."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/6972?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6972. Citizen suits","tname":"The Public Health and Welfare","by":{"1":"38","2":"36"}},{"t":"usc","label":"42 U.S.C. § 9607","url":"https://www.law.cornell.edu/uscode/text/42/9607","subs":["(a)(4)"],"by":{"1":"38"}},{"t":"case","label":"Alexander v. Hillman","cite":"296 U.S. 222","y":1935,"id":"scdb/1935-002","sc":1,"sum":"In a suit in the District Court in which receivers were appointed to collect and distribute the assets of a corporation, claims were filed by individuals who as directors and officers had controlled and dominated the corporation's affairs, and by other companies, also controlled and used by them. In response to the claims, the receivers filed in the same court an ancillary bill, separately numbered but not praying …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20","3":"2, 7, 9"}},{"t":"case","label":"Belford v. Scribner","cite":"144 U.S. 488","y":1892,"id":"scdb/1891-186","sc":1,"sum":"In. an equity suit for the infringement of a copyright, where the defendant appeals from the final decree, if exceptions were taken to the report of a master in favor of the plaintiff, it is the duty of the appellant to bring the exceptions into this court, as part of the record; and, if he took no exceptions, the report stands without exception. (","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Brown v. Swann","cite":"35 U.S. 497","y":1836,"id":"scdb/1836-033","sc":1,"sum":"The statute of Virginia against usury, provides that “ any borrower of money or goods, may exhibit a bill in chancery against the lenders, and compel them to discover on oath the money they really lent; and all bargains, contracts or shifts which shall have passed between them relative to such loan or the repayment thereof, and the interest and consideration of the same: and if thereupon it shall appear that more …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"38"}},{"t":"case","label":"Bouie v. City of Columbia","cite":"378 U.S. 347","y":1964,"id":"1963/10","sc":1,"sum":"The State Supreme Court, in giving retroactive application to its new construction of the statute, has deprived petitioners of their right to fair warning of a criminal prohibition, and thus has violated the Due Process Clause of the Fourteenth Amendment. Pp. 348-363. 239 S. C. 570, 124 S. E. 2d 332, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"45"}},{"t":"case","label":"Camp v. Boyd","cite":"229 U.S. 530","y":1913,"id":"scdb/1912-259","sc":1,"sum":"Parties in possession of land under titles from various sources and having the equitable, as well as the legal, title to a portion of it and the equitable, but not the legal, title to the remainder, may, under the circumstances of this case, properly invoke the aid of equity to restrain other parties from maintaining ejectment suits and to adjudicate the title to the entire tract in a single suit.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20","3":"9"}},{"t":"case","label":"Civil Aeronautics Bd. v. Delta Air Lines, Inc.","cite":"367 U.S. 316","y":1961,"id":"1960/492","sc":1,"ar":1,"sum":"Once a certificate of public convenience and necessity granted by the Civil Aeronautics Board to an air line has become effective under § 401 (f) of the Federal Aviation Act of 1958, the Board may not alter it without the formal notice and hearing required by § 401 (g)-even though the Board, at the time of certification, has purported to reserve jurisdiction to make summary modifications pursuant to petitions for …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40","3":"22"}},{"t":"case","label":"Colburn v. Sims","cite":"67 Eng. Rep. 223","y":1843,"court":"Ch.","url":"https://www.courtlistener.com/c/Eng.%20Rep./67/223/","by":{"2":"19"}},{"t":"case","label":"Cortez Byrd Chips, Inc. v. Bill Harbert Constr. Co.","cite":"529 U.S. 193","y":2000,"id":"1999/98-1960","sc":1,"sum":"Delivered by Justice David H. Souter, the Court held that the \"FAA's venue provisions are permissive, allowing a motion to confirm, vacate, or modify to be brought either in the district where the award was made or in any district proper under the general venue statute.\" Writing for the Court, Justice Souter reasoned that because both the history and function of the FAA's venue provisions dictate that they were meant to expand, not limit, venue choice, it was appropriate for Cortez Byrd to seek to vacate the arbitrator's award in federal court in Mississippi.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Dean v. Mason","cite":"61 U.S. 198","y":1858,"id":"scdb/1857-028","sc":1,"op":4,"sum":"In suits for the infringement of a patent right, the rule of dam.' es is the amount which the infringer actually realized in profits, not what he night have made hf reasonable diligence.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Envtl. Def. v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"sum":"Unanswered and No. In a unanimous opinion by Justice David Souter, the Court ruled that the EPA need not interpret \"modification\" in PSD regulations the same way the term is interpreted in NSPS regulations. The Court's opinion acknowledged that two occurrences of the same term - sharing the same definition - are normally given the same meaning.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"FTC v. Febre","cite":"128 F.3d 530","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/128/530/","by":{"2":"28"}},{"t":"case","label":"FTC v. Pantron I Corp.","cite":"33 F.3d 1088","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/33/1088/","by":{"2":"28"}},{"t":"case","label":"FTC v. U.S. Oil & Gas Corp.","cite":"748 F.2d 1431","y":1984,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/748/1431/","by":{"2":"8, 27"}},{"t":"case","label":"FTC v. Virginia Homes Mfg. Corp.","cite":"509 F. Supp. 51","y":1981,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp./509/51/","op":1,"by":{"2":"8"}},{"t":"case","label":"FTC v. Wyndham Worldwide Corp.","cite":"799 F.3d 236","y":2015,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/799/236/","by":{"2":"45"}},{"t":"case","label":"Hamilton-Brown Shoe Co. v. Wolf Bros. & Co.","cite":"240 U.S. 251","y":1916,"id":"scdb/1915-097","sc":1,"sum":"The words “The American Girl” as applied to women’s shoes is not a geographical or descriptive term signifying that the articles are manufactured in America, or intended to be.sold therein; nor does it indicate qualities or characteristics of the article.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Heater v. FTC","cite":"503 F.2d 321","y":1974,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/503/321/","by":{"2":"7"}},{"t":"case","label":"Hecht Co. v. Bowles","cite":"321 U.S. 321","y":1944,"id":"scdb/1943-092","sc":1,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942, the grant of an injunction, upon application of the Administrator and a showing that the defendant has engaged in acts or practices violative of § 4 of the Act, is not mandatory but is in the discretion of the court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25, 41"}},{"t":"case","label":"Hogg v. Kirby","cite":"32 Eng. Rep. 336","y":1803,"court":"Ch.","url":"https://www.courtlistener.com/c/Eng.%20Rep./32/336/","by":{"2":"19"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Huguenin v. Basely","cite":"33 Eng. Rep. 722","y":1808,"court":"Ch.","url":"https://www.courtlistener.com/c/Eng.%20Rep./33/722/","by":{"2":"29"}},{"t":"case","label":"Jesus College v. Bloom","cite":"26 Eng. Rep. 953","y":1745,"court":"Ch.","url":"https://www.courtlistener.com/c/Eng.%20Rep./26/953/","by":{"2":"17, 18"}},{"t":"case","label":"Livingston v. Woodworth","cite":"56 U.S. 546","y":1854,"id":"scdb/1853-038","sc":1,"sum":"Where the assignors of. a pateijt-right were joined with the assignee for a particular locality, in a bill for an injunction to restrain' a defendant from the use of the machine patented, and the defendant raised, in this court, and after a final decree, an objection arising from a misjoinder of parties, the objection comes too late..","sumSrc":"Headnote (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"2":"26"}},{"t":"case","label":"Manhattan Properties, Inc. v. Irving Trust Co.","cite":"291 U.S. 320","y":1934,"id":"scdb/1933-048","sc":1,"sum":"1. The claim of a landlord for future rents based on a covenant to p'ay rent in a lease terminated by reintry on the bankruptcy of the tenant, is not a provable debt under § 63 (a) of the Bankruptcy Act. P. 332. So held in view of the great weight of judicial authority construing that section and similar provisions of earlier Acts, and in view of the legislative history of the subject.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"Nationwide Mut. Ins. Co. v. Darden","cite":"503 U.S. 318","y":1992,"id":"1991/90-1802","sc":1,"sum":"Contracts between petitioners Nationwide Mutual Insurance Co. et al. and respondent Darden provided, among other things, that Darden would sell only Nationwide policies, that Nationwide would enroll him in a company retirement plan for agents, and that he would forfeit his entitlement to plan benefits if, within a year of his termination and 25 miles of his prior business location, he sold insurance for Nationwide's …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"NLRB v. Bell Aerospace Co.","cite":"416 U.S. 267","y":1974,"id":"1973/72-1598","sc":1,"sum":"On a petition by a labor union for a representation election, the National Labor Relations Board (NLRB) held that the buyers employed by respondent company constituted an appropriate collective-bargaining unit and directed an election. The NLRB stated that even though the buyers might be \"managerial employees\" they were nevprtheless covered by the National Labor Relations Act (NLRA) in the absence of any showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"50"}},{"t":"case","label":"Osborn v. Bank of the United States","cite":"22 U.S. 738","y":1824,"id":"1789-1850/22us738","sc":1,"sum":"In a 6-to-1 decision, the Court held that the circuit court properly ruled against Ohio officials and that the Ohio law was \"repugnant to the Constitution.\" The Court held that the Eleventh Amendment was limited to suits in which a state was party on the record, and that Ohio was not the target of the suit in the case at hand.","sumSrc":"Oyez","by":{"2":"29, 30"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"25"}},{"t":"case","label":"Rubber Co. v. Goodyear","cite":"76 U.S. 788","y":1869,"id":"scdb/1869-139","sc":1,"sum":"1. \"Where a patentee dies, the surrogate of the place where the decedent was domiciled properly has jurisdiction to take probate of his will and issue letters testamentary.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"SEC v. Manor Nursing Ctrs., Inc.","cite":"458 F.2d 1082","y":1972,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/458/1082/","by":{"2":"26"}},{"t":"case","label":"SEC v. Tex. Gulf Sulphur Co.","cite":"446 F.2d 1301","y":1971,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/446/1301/","by":{"2":"26"}},{"t":"case","label":"Sheldon v. Metro-Goldwyn Pictures Corp.","cite":"309 U.S. 390","y":1940,"id":"scdb/1939-111","sc":1,"sum":"1. That clause of § 25 (b) of the Copyright Act which authorizes recovery from an infringer, \"in lieu of actual damages and profits,\" of \"such 'damages as to the court shall appear to be just,\" is inapplicable where the only matter in question is the apportionment of profits established.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12, 22"}},{"t":"case","label":"Standard Oil Co. v. United States","cite":"221 U.S. 1","y":1911,"id":"1900-1940/221us1","sc":1,"sum":"Standard Oil lost, but White, for the majority, managed to amend the language of the Sherman Act such that only \"unreasonable\" contracts and combinations in restraint of trade would violate the law. Heretofore, the Act made all contracts and combinations in retraint of trade into law violations. In this case, the record shows that the Standard Oil trust was unreasonable.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Stevens v. Gladding","cite":"58 U.S. 447","y":1855,"id":"scdb/1854-046","sc":1,"sum":"Whether patent-rights and copyrights, held under the laws of the United States, are subject to seizure and sale on execution, is a question upon which the court dogs not express an opinion in the present case.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"12, 17, 21","3":"12, 13"}},{"t":"case","label":"Stribley v. Hawke","cite":"26 Eng. Rep. 961","y":1744,"court":"Ch.","url":"https://www.courtlistener.com/c/Eng.%20Rep./26/961/","by":{"2":"29"}},{"t":"case","label":"Tilghman v. Procter","cite":"125 U.S. 136","y":1888,"id":"scdb/1887-171","sc":1,"sum":"One having an interest in all fees and other sums to be recovered under a patent, but not shown to have'any interest, legal or equitable, in the patent itself, need not be made a party to a bill in equity for its infringement.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"3, 12, 17, 18, 21, 22","3":"13"}},{"t":"case","label":"Tull v. United States","cite":"481 U.S. 412","y":1987,"id":"1986/85-1259","sc":1,"sum":"The Clean Water Act (Act) authorizes injunctive relief against violators (33 U. S. C. § 1319(b)) and subjects them to a civil penalty not to exceed $10,000 per day (§ 1319(d)). After denying petitioner's timely demand for a jury trial in the Government's suit for relief under §§ 1319(b) and 1319(d), the District Court imposed civil penalties and granted injunctive relief against petitioner. The Court of Appeals …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12, 19","3":"8"}},{"t":"case","label":"United States v. Grote","cite":"961 F.3d 105","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/961/105/","by":{"2":"10, 11"}},{"t":"case","label":"United States v. Morton Salt Co.","cite":"338 U.S. 632","y":1950,"id":"scdb/1949-040","sc":1,"sum":"Under § 5 of the Federal Trade Commission Act, the Commission ordered respondent corporations and others to cease and desist from certain trade practices. The Court of Appeals affirmed the order with modifications and commanded compliance. The decree directed that reports of compliance be filed with the Commission within 90 days, reserved jurisdiction to enter further orders to enforce compliance, and provided that …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40"}},{"t":"case","label":"United States v. Union Pacific R. Co.","cite":"160 U.S. 1","y":1895,"id":"scdb/1895-047","sc":1,"sum":"The objects which Congress sought to accomplish by the act of July 1,1862, c. 120, 12 Stat. 489, granting a subsidy to aid in the construction of both a railroad and a telegraph line from the Missouri River to the Pacific Ocean, and by the act of July 2, 1864, c. 216, 13 Stat. 366, amendatory thereof, were the construction, the maintenance and the operation of both a railroad and a telegraph line between those two …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20","3":"9"}},{"t":"usc","label":"15 U.S.C. § 26","url":"https://www.law.cornell.edu/uscode/text/15/26","by":{"2":"37"}},{"t":"usc","label":"15 U.S.C. § 68e","url":"https://www.law.cornell.edu/uscode/text/15/68e","subs":["(b)"],"by":{"2":"5, 26"}},{"t":"usc","label":"15 U.S.C. § 69g","url":"https://www.law.cornell.edu/uscode/text/15/69g","subs":["(b)"],"by":{"2":"5, 26"}},{"t":"usc","label":"15 U.S.C. § 70f","url":"https://www.law.cornell.edu/uscode/text/15/70f","by":{"2":"5, 26"}},{"t":"usc","label":"15 U.S.C. § 77t","url":"https://www.law.cornell.edu/uscode/text/15/77t","subs":["(b)"],"by":{"2":"25"}},{"t":"usc","label":"15 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/15/1601","by":{"2":"9"}},{"t":"usc","label":"15 U.S.C. § 1667f","url":"https://www.law.cornell.edu/uscode/text/15/1667f","by":{"2":"9"}},{"t":"law","label":"Pub. L. No. 103-312","by":{"2":"27, 28"}},{"t":"law","label":"Pub. L. No. 107-204","url":"https://www.govinfo.gov/link/plaw/107/public/204","by":{"2":"26"}},{"t":"law","label":"Pub. L. No. 109-455","url":"https://www.govinfo.gov/link/plaw/109/public/455","by":{"2":"28"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"sum":"1. Where the complaint seeks recovery squarely on the ground of violation of plaintiffs' rights under the Fourth and Fifth Amendments, a federal district court has jurisdiction of a suit against agents of the Federal Government to recover damages in excess of $3,000 alleged to have been suffered by the plaintiffs as a result of such violations-even though neither the Constitution nor the Congress has provided for …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"12"}},{"t":"case","label":"Cain v. Cain","cite":"20 N.Y.S. 45","y":1892,"court":"Sup. Ct. N.Y. Cnty.","url":"https://www.courtlistener.com/c/N.Y.S./20/45/","by":{"3":"6"}},{"t":"case","label":"City of Oklahoma City v. Tuttle","cite":"471 U.S. 808","y":1985,"id":"1984/83-1919","sc":1,"sum":"The Court held that the district court’s instructions to the jury improperly allowed a plaintiff to impose liability on the city without proof of a single action taken by a municipal policy maker.","sumSrc":"Oyez","by":{"3":"26"}},{"t":"case","label":"Comm’rs of Wash. Cnty. v. Sch. Comm’rs","cite":"26 A. 115","y":1893,"court":"Md.","url":"https://www.courtlistener.com/c/A./26/115/","by":{"3":"5"}},{"t":"case","label":"FTC v. AbbVie Inc.","cite":"976 F.3d 327","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/976/327/","op":1,"by":{"3":"20"}},{"t":"case","label":"Memphis Grocery Co. v. Trotter","cite":"7 So. 550","y":1890,"court":"Miss.","url":"https://www.courtlistener.com/c/So./7/550/","by":{"3":"5"}},{"t":"case","label":"Montanile v. Bd. of Trs. of Nat’l Elevator Indus. Health Benefit Plan","cite":"577 U.S. 136","y":2016,"id":"2015/14-723","sc":1,"sum":"The Court determined that the Employee Retirement Income Security Act of 1974 does not allow for a suit to recover reimbursement of an asset that has been fully disbursed on non-traceable items such as services.","sumSrc":"Oyez","by":{"3":"9, 11"}},{"t":"case","label":"Nat’l Ass’n of Home Builders v. Defs. of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Root v. Ry. Co.","cite":"105 U.S. 189","y":1882,"id":"scdb/1881-134","sc":1,"ar":1,"by":{"3":"10, 13, 14"}},{"t":"case","label":"SCA Hygiene Prods. Aktiebolag v. First Quality Baby Prods., LLC","cite":"137 S. Ct. 954","y":2017,"id":"2016/15-927","sc":1,"sum":"The Court determined that an unreasonable delay in litigation cannot bar claims for patent infringement that are brought within the six-year statutory period of limitations.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"op":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"3":"15"}}]};